package got.client.special;
import com.mojang.blaze3d.vertex.*; import com.mojang.math.Axis; import org.joml.Matrix4f; import got.GOTMod; import got.special.GOTMarshWraithBallEntity; import net.minecraft.client.renderer.*; import net.minecraft.client.renderer.texture.OverlayTexture; import net.minecraft.client.renderer.entity.*; import net.minecraft.resources.ResourceLocation;
public final class GOTMarshWraithBallRenderer extends EntityRenderer<GOTMarshWraithBallEntity>{private static final ResourceLocation TEX=new ResourceLocation(GOTMod.MOD_ID,"textures/entity/essos/mossovy/wraith/marshwraith_ball.png");public GOTMarshWraithBallRenderer(EntityRendererProvider.Context c){super(c);}public void render(GOTMarshWraithBallEntity e,float y,float pt,PoseStack ps,MultiBufferSource buf,int light){ps.pushPose();ps.mulPose(entityRenderDispatcher.cameraOrientation());ps.mulPose(Axis.YP.rotationDegrees(180));float s=.75F;ps.scale(s,s,s);Matrix4f m=ps.last().pose();VertexConsumer v=buf.getBuffer(RenderType.entityCutoutNoCull(TEX));vertex(v,m,-.5F,-.5F,0,1);vertex(v,m,.5F,-.5F,1,1);vertex(v,m,.5F,.5F,1,0);vertex(v,m,-.5F,.5F,0,0);ps.popPose();}private static void vertex(VertexConsumer v,Matrix4f m,float x,float y,float u,float q){v.vertex(m,x,y,0).color(255,255,255,220).uv(u,q).overlayCoords(OverlayTexture.NO_OVERLAY).uv2(15728880).normal(0,1,0).endVertex();}public ResourceLocation getTextureLocation(GOTMarshWraithBallEntity e){return TEX;}}
